def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    def is_ccc(start):
        for i in range(start, start + 3):
            if i >= n:
                return False
            if my[i] != 'C' or op[i] != 'C':
                return False
        return True

    # If opponent has cooperated a lot, keep cooperating but punish defections.
    op_c = sum(1 for a in op if a == 'C')
    my_c = sum(1 for a in my if a == 'C')

    # Detect long runs of cooperation and try to exploit occasionally.
    # But be careful: against nice strategies, defecting loses future cooperations.

    # Defect if opponent defected in the last round, unless we can detect forgiveness.
    if n >= 1 and op[-1] == 'D':
        # Grudger-like behavior: defect once to punish, then return to C if opponent does.
        if n >= 2 and op[-2] == 'D':
            # Two consecutive defections: check if this is a pattern
            if n >= 4:
                d_count_recent = sum(1 for a in op[-4:] if a == 'D')
                if d_count_recent >= 3:
                    return 'D'
            return 'D'
        # Single defection by opponent: punish with D
        return 'D'

    # Opponent cooperated last round.
    if n >= 2 and op[-1] == 'C' and op[-2] == 'C':
        # Opponent seems nice. Exploit slightly once every many rounds?
        # Use rng for deterministic-ish exploitation based on round.
        if n > 20 and n % 17 == 0 and op_c > n * 0.8:
            return 'D'

    # Early game: cooperate to build trust.
    if n < 5:
        return 'C'

    # If opponent has defected significantly more than we have, be defensive.
    if op_c < my_c - 2:
        return 'D'

    # TFT-like with occasional forgiveness: cooperate.
    return 'C'
